WHILE xspk<=xspn DO
xspch:=mid(xsps,xspk,1);
IF xspquoted==0 AND mid(xsps,xspk,xspni)==xspi THEN
xspr:=xspr+"@@XSIMP_I@@"; xspk:=xspk+xspni;
ELSE
xspr:=xspr+xspch; xspk:=xspk+1;
IF xspescape==1 THEN xspescape:=0;
ELSE
IF xspch==char(92) THEN xspescape:=1;
ELSE IF xspch==char(34) THEN xspquoted:=1-xspquoted; END; END;
END;
END;
END;
RETURN xspr;
END

