IF inString(string(xsav),xsaname)==0 THEN RETURN [1,xsav]; END;
IF type(xsav)==DOM_IDENT THEN
IF string(xsav)==xsaname THEN RETURN [1,i]; END;
RETURN [1,xsav];
END;
IF type(xsav)<>DOM_LIST AND type(xsav)<>DOM_SYMBOLIC THEN RETURN [1,xsav]; END;
IF xsad>=24 THEN RETURN [0]; END;
