IF string(xsan[2])<>string(xsav[xsak]) THEN xsar[xsak]:=xsan[2]; END;
END;
RETURN [1,xsar];
END;
xsah:=string(xshead(xsav));


IF xsah=="of" OR xsah=="'of'" THEN RETURN [0]; END;
xsal:=[op(xsav)];
FOR xsak FROM 1 TO size(xsal) DO
IF string(xsal[xsak])==string(xsav) THEN RETURN [0]; END;
