definition:
xsphold(xsps):=BEGIN
LOCAL xspr,xspname,xsptextvalue,xspk,xspquoted,xspescape,xspch,xspfound;
IF inString(xsps,"@@XSIMP_I@@")==0 THEN RETURN expr("quote("+xsps+")"); END;

xspname:="xsppimagatom";
WHILE inString(xsps,xspname)>0 DO xspname:=xspname+"x"; END;
xsptextvalue:=""; xspk:=1; xspquoted:=0; xspescape:=0; xspfound:=0;
WHILE xspk<=size(xsps) DO
xspch:=mid(xsps,xspk,1);
IF xspquoted==0 AND mid(xsps,xspk,11)=="@@XSIMP_I@@" THEN
xsptextvalue:=xsptextvalue+xspname; xspk:=xspk+11; xspfound:=1;
ELSE
xsptextvalue:=xsptextvalue+xspch; xspk:=xspk+1;
IF xspescape==1 THEN xspescape:=0;
ELSE
IF xspch==char(92) THEN xspescape:=1;
ELSE IF xspch==char(34) THEN xspquoted:=1-xspquoted; END; END;
END;
END;
END;
xspr:=expr("quote("+xsptextvalue+")");
IF xspfound THEN
xspr:=xspatomwalk(xspr,xspname,0);
IF xspr[1]==0 THEN RETURN undef; END;
RETURN xspr[2];
END;
RETURN xspr;
END

