(type((XSIMP(xsuinput):=BEGIN
LOCAL xsures,xsuoriginal,xsuoldroots,xsunewroots,xsuoldarg,xsunewarg,xsucheckroot,xsurootok,xsusafe,xsuwork;
IF NOT xsuindexok(0) THEN RETURN "XSIMP 1.8.7: CAS index starts at 0; run of:=1"; END;
IF type(xsinitok)<>DOM_FUNC THEN RETURN "XSIMP 1.8.7: run XSIMPKIT187 from Program Catalog to refresh CAS functions"; END;
IF NOT xsinitok(0) THEN RETURN "XSIMP 1.8.7: run XSIMPKIT187 from Program Catalog to refresh CAS functions"; END;
IF size(string(xsuinput))>1600 THEN RETURN "XSIMP: input exceeds 1600 characters"; END;
xsuoriginal:=xsuinput;
IF type(xsuinput)==DOM_STRING THEN xsuoriginal:=expr("quote("+xsuinput+")"); END;
xsusafe:=xsidauto(xsuoriginal); xsuwork:=xsusafe[1];


IF xsusafe[2] OR (string(xsuwork)<>string(xsuoriginal) AND xshypnatural(xsuwork)) THEN RETURN xspfauto(xsuwork); END;
xsucheckroot:=0;



IF type(xsuoriginal)==DOM_SYMBOLIC THEN
IF size(xsppa(xsuoriginal,0))==2 THEN
xsuoldroots:=xshyproots(xsuoriginal,0);
IF size(xsuoldroots)==2 AND xsuoldroots[1]==1 THEN
xsuoldarg:=[op(xsuoldroots[2])]; xsuoldarg:=xsuoldarg[1];
IF xshyppoly(xsuoldarg,0) AND size(lname(xsuoldarg))>0 THEN xsucheckroot:=1; END;
END;
END;
END;
xsures:=xsutree(xsuwork);
IF type(xsures)==DOM_STRING THEN RETURN xsures; END;


IF type(xsures)==DOM_LIST THEN RETURN xspfauto(xsuorigselect(xsuoriginal,xsuend(xsufold(xsures,0)),0)); END;
xsures:=xsuend(xsufold(xsscalar(xsures),0));
IF xsucheckroot THEN
xsurootok:=0; xsunewroots:=xshyproots(xsures,0);
IF size(xsunewroots)==2 AND xsunewroots[1]==1 THEN
xsunewarg:=[op(xsunewroots[2])]; xsunewarg:=xsunewarg[1];
IF xshyppoly(xsunewarg,0) THEN
IF string(ratnormal(xsuoldarg-xsunewarg))=="0" THEN xsurootok:=1; END;
END;
END;
IF NOT xsurootok THEN RETURN xspfauto(xspresent(xsuoriginal)); END;
END;
RETURN xspfauto(xsuorigselect(xsuoriginal,xsuorigselect(xsuwork,xsures,0),0));
END))==DOM_FUNC)

definition:
XSDIAG(xsuunused):=BEGIN
IF type(xsinitok)<>DOM_FUNC THEN RETURN "XSIMP 1.8.7: run XSIMPKIT187 from Program Catalog to refresh CAS functions"; END;
IF NOT xsinitok(0) THEN RETURN "XSIMP 1.8.7: run XSIMPKIT187 from Program Catalog to refresh CAS functions"; END;
RETURN ["1.8.7",xsucorecheck(0),xsptext(exp((2-sqrt(3))*ln(2)),0),string(xspresent(exp((2-sqrt(3))*ln(2))))];
END

