definition:
XSCHECK(xsuunused):=BEGIN
LOCAL xsucheck;
IF type(xsinitok)<>DOM_FUNC THEN RETURN "XSIMP 1.8.7: run XSIMPKIT187 from Program Catalog to refresh CAS functions"; END;
IF NOT xsinitok(0) THEN RETURN "XSIMP 1.8.7: run XSIMPKIT187 from Program Catalog to refresh CAS functions"; END;
xsucheck:=xsucorecheck(0);
IF xsucheck<>"XSIMP 1.8.7 CHECK OK" THEN RETURN xsucheck; END;
IF NOT xsmpisradian(0) THEN RETURN "XSIMP 1.8: mixed identities require CAS radians"; END;
IF NOT xsmpunbound(expr("quote(xsmpchecku+xsmpcheckv)"),0) THEN
RETURN "XSIMP 1.8: check symbols bound; no state changed";
END;
IF string(XSIMP("sinh(xsmpchecku)+i*sin(i*xsmpchecku)"))<>"0" THEN RETURN "XSIMP 1.8: mixed identity failed"; END;
IF string(XSIMP("cosh(xsmpchecku)^2+sin(i*xsmpchecku)^2"))<>"1" THEN RETURN "XSIMP 1.8: square identity failed"; END;
IF string(XSIMP("cosh(xsmpchecku+xsmpcheckv)-cos(i*xsmpchecku)*cosh(xsmpcheckv)+i*sin(i*xsmpchecku)*sinh(xsmpcheckv)"))<>"0" THEN RETURN "XSIMP 1.8: addition identity failed"; END;
IF inString(string(XSIMP("exp(xsmpchecku)-exp(-xsmpchecku)")),"sinh(")==0 THEN RETURN "XSIMP 1.8: exponential pairing failed"; END;
IF type(xsphold("@@XSIMP_I@@"))<>DOM_COMPLEX THEN RETURN "XSIMP: exact complex literal parsing failed"; END;
IF string(normal(-i*xsphold("@@XSIMP_I@@*xsmpcheckv")))<>"xsmpcheckv" THEN RETURN "XSIMP: imaginary constant arithmetic failed"; END;
xsucheck:=string(XSIMP("exp(xsmpchecku+i*xsmpcheckv)-exp(xsmpchecku-i*xsmpcheckv)"));
IF inString(xsucheck,"sinh(")>0 OR inString(xsucheck,"SINH(")>0 OR
(inString(xsucheck,"sin(")==0 AND inString(xsucheck,"SIN(")==0) THEN RETURN "XSIMP 1.8.7: imaginary exponential presentation failed"; END;
xsucheck:=string(xspresent(xsphold("2*exp(xsmpchecku)*SINH(@@XSIMP_I@@*xsmpcheckv)")));
IF inString(xsucheck,"sinh(")>0 OR inString(xsucheck,"SINH(")>0 OR
(inString(xsucheck,"sin(")==0 AND inString(xsucheck,"SIN(")==0) THEN RETURN "XSIMP 1.8.7: uppercase hyperbolic presentation failed"; END;
RETURN "XSIMP 1.8.7 CHECK OK";
END

